using IndieRun;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Refuse(Action run){try{run();}catch(Exception ex)when(ex is IOException or InvalidDataException or UnauthorizedAccessException or OperationCanceledException){return;}throw new Exception("Expected refusal");}
    static void Hook(BackupEngine e,Action<string> hook)=>typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,hook);
    static void CopyMode(BackupEngine e)=>typeof(BackupEngine).GetProperty("ForceCopyMove",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,true);
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(o,args);
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static (BackupEngine Engine,BackupJob Job,Package Game) Prepare(string dir,bool selective=false,bool copy=false)
    {var p=Fixture(dir,selective);var engine=new BackupEngine(Path.Combine(dir,"records"));if(copy)CopyMode(engine);var job=Task.Run(()=>engine.PrepareDirectMoveAsync(p,[])).GetAwaiter().GetResult();return(engine,job,p);}
    static void NoPayload(BackupEngine e,BackupJob j)=>Check(j.WithoutBackup&&!Directory.Exists(e.Payload(j)),"A persistent game backup payload was created");
    static int Child(string[] args)
    {
        var e=new BackupEngine(Path.Combine(args[1],"records"));var job=e.ListJobs(false).Single();Hook(e,p=>{if(p==args[2]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}});
        if(args[0]=="--undo-child")e.UndoMoveAsync(job.Id,e.ListMoves(false).Single().Id).GetAwaiter().GetResult();else{if(args[3]=="copy")CopyMode(e);e.MoveAsync(job.Id,Path.Combine(args[1],"target","Moved")).GetAwaiter().GetResult();}return 0;
    }
    static void KillChild(string folder,string point,bool copy,bool undo)
    {
        var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};foreach(var a in new[]{undo?"--undo-child":"--move-child",folder,point,copy?"copy":"rename"})start.ArgumentList.Add(a);
        using var process=Process.Start(start)!;var ready=process.StandardOutput.ReadLineAsync();if(!ready.Wait(15000)||ready.Result!="READY"){if(!process.HasExited)process.Kill(true);throw new Exception("Crash checkpoint was not reached: "+point);}process.Kill(true);process.WaitForExit();
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    [STAThread]static int Main(string[] args)
    {
        if(args[0].StartsWith("--"))return Child(args);
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("manifest-only-no-payload-or-game-copy",dir=>{var f=Prepare(dir);NoPayload(f.Engine,f.Job);Check(Directory.GetFiles(Path.Combine(dir,"records"),"*",SearchOption.AllDirectories).Sum(p=>new FileInfo(p).Length)<100_000,"Record storage resembles a backup copy");});
        foreach(var copy in new[]{false,true})Test("move-and-return-"+(copy?"copy":"rename"),dir=>{var f=Prepare(dir,copy:copy);var source=f.Game.Source;var moved=f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult();Check(moved.WithoutBackup&&moved.Status=="Completed"&&!Directory.Exists(source),"Direct move failed");NoPayload(f.Engine,f.Job);var undone=f.Engine.UndoMoveAsync(f.Job.Id,moved.Id).GetAwaiter().GetResult();Check(undone.Status=="RolledBack"&&File.Exists(Path.Combine(source,"Game.exe"))&&!Directory.Exists(moved.Destination),"Return failed without payload");NoPayload(f.Engine,f.Job);});
        Test("selective-move-and-return-keeps-excluded-files",dir=>{var f=Prepare(dir,true);var move=f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(f.Game.Source,"Extras","guide.txt"))&&!File.Exists(Path.Combine(f.Game.Source,"Game.exe")),"Selected projection wrong");f.Engine.UndoMoveAsync(f.Job.Id,move.Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&File.Exists(Path.Combine(f.Game.Source,"Extras","guide.txt")),"Selective return lost content");NoPayload(f.Engine,f.Job);});
        Test("cancelled-copy-cleans-owned-temporary-game-data",dir=>{var f=Prepare(dir,copy:true);using var c=new CancellationTokenSource();Hook(f.Engine,p=>{if(p=="Moving-chunk")c.Cancel();});Refuse(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved"),cancellation:c.Token).GetAwaiter().GetResult());Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&!Directory.Exists(Path.Combine(dir,"target","Moved")),"Cancellation lost original");Check(!Directory.GetDirectories(Path.Combine(dir,"target"),".indierun-move-*").Any(),"Cancelled operation retained a large temporary copy");NoPayload(f.Engine,f.Job);});
        Test("changed-source-is-preserved",dir=>{var f=Prepare(dir);File.AppendAllText(Path.Combine(f.Game.Source,"Game.exe"),"changed");Refuse(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult());Check(File.ReadAllText(Path.Combine(f.Game.Source,"Game.exe")).EndsWith("changed"),"Changed source overwritten");});
        Test("foreign-destination-not-overwritten",dir=>{var f=Prepare(dir);var target=Path.Combine(dir,"target","Moved");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"foreign.txt"),"keep");Refuse(()=>f.Engine.MoveAsync(f.Job.Id,target).GetAwaiter().GetResult());Check(File.ReadAllText(Path.Combine(target,"foreign.txt"))=="keep"&&Directory.Exists(f.Game.Source),"Foreign content changed");});
        Test("direct-record-is-not-restorable-as-a-backup",dir=>{var f=Prepare(dir);Refuse(()=>f.Engine.RestoreAsync(f.Job.Id,Path.Combine(dir,"restore")).GetAwaiter().GetResult());Refuse(()=>f.Engine.VerifyAsync(f.Job.Id).GetAwaiter().GetResult());NoPayload(f.Engine,f.Job);});
        Test("preparation-cancel-does-not-copy-or-move",dir=>{var p=Fixture(dir);var e=new BackupEngine(Path.Combine(dir,"records"));using var c=new CancellationTokenSource();c.Cancel();Refuse(()=>e.PrepareDirectMoveAsync(p,[],cancellation:c.Token).GetAwaiter().GetResult());Check(Directory.Exists(p.Source)&&!Directory.GetDirectories(Path.Combine(dir,"records"),"payload",SearchOption.AllDirectories).Any(),"Cancelled hash preparation copied data");});
        Test("same-volume-rename-does-not-require-game-copy-space",dir=>{var f=Prepare(dir);typeof(BackupEngine).GetProperty("AvailableBytesOverride",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(f.Engine,(Func<long>)(()=>0));var move=f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult();Check(move.Status=="Completed"&&!Directory.Exists(f.Game.Source),"Direct rename required a whole-game backup allocation");NoPayload(f.Engine,f.Job);});
        Test("copy-move-still-checks-temporary-capacity",dir=>{var f=Prepare(dir,copy:true);typeof(BackupEngine).GetProperty("AvailableBytesOverride",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(f.Engine,(Func<long>)(()=>0));Refuse(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult());Check(Directory.Exists(f.Game.Source)&&!Directory.Exists(Path.Combine(dir,"target","Moved")),"Insufficient copy space lost original");});
        Test("missing-destination-data-cannot-be-restored-from-a-nonexistent-backup",dir=>{var f=Prepare(dir,copy:true);var move=f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult();File.Delete(Path.Combine(move.Destination,"Data","large.bin"));Refuse(()=>f.Engine.UndoMoveAsync(f.Job.Id,move.Id).GetAwaiter().GetResult());Check(File.Exists(Path.Combine(move.Destination,"Game.exe"))&&!Directory.Exists(f.Game.Source),"Damaged destination triggered destructive fake restoration");NoPayload(f.Engine,f.Job);});
        foreach(var point in new[]{"Moving-chunk","Moving-file","move-before-capture","move-captured","move-published","move-remove-file"})Test("process-kill-copy-"+point,dir=>{var f=Prepare(dir,copy:true);KillChild(dir,point,true,false);var move=f.Engine.ListMoves().Single();f.Engine.UndoMoveAsync(f.Job.Id,move.Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&!Directory.Exists(move.Destination),"Crash recovery failed");NoPayload(f.Engine,f.Job);});
        Test("process-kill-rename-published",dir=>{var f=Prepare(dir);KillChild(dir,"move-published",false,false);f.Engine.UndoMoveAsync(f.Job.Id,f.Engine.ListMoves().Single().Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe")),"Rename crash not recovered");});
        foreach(var point in new[]{"selective-published","selective-remove-file"})Test("process-kill-"+point,dir=>{var f=Prepare(dir,true);KillChild(dir,point,false,false);f.Engine.UndoMoveAsync(f.Job.Id,f.Engine.ListMoves().Single().Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&File.Exists(Path.Combine(f.Game.Source,"Extras","guide.txt")),"Selective crash lost files");});
        foreach(var point in new[]{"undo-prepared","move-remove-file","undo-source-restored"})Test("process-kill-return-"+point,dir=>{var f=Prepare(dir,copy:true);f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved")).GetAwaiter().GetResult();KillChild(dir,point,true,true);var result=f.Engine.ResumeMoveAsync(f.Job.Id,f.Engine.ListMoves().Single().Id).GetAwaiter().GetResult();Check(result.Status=="RolledBack"&&File.Exists(Path.Combine(f.Game.Source,"Game.exe")),"Return recovery required missing backup payload");});
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("mainwindow-direct-mode-stores-no-real-backup",dir=>{var w=Window(dir,out var p);try{Wait((Task)Call(w,"ExecuteMoveListWithModeAsync",new MoveSelection(new[]{p},Get<List<Package>>(w,"packages")).Items(Path.Combine(dir,"library")),Path.Combine(dir,"library"),true)!);Check(!Directory.Exists(Path.Combine(dir,"backups")),"Direct move touched the configured backup storage");var engine=new BackupEngine(Path.Combine(dir,"records"));var job=engine.ListJobs().Single();Check(job.WithoutBackup&&engine.ListMoves().Single().Status=="Completed"&&!p.Backup&&p.Done,"Move mode or UI backup flag wrong");NoPayload(engine,job);Check(Get<OperationStatus>(w,"operationStatus").WithoutBackup,"Summary lost no-backup mode");Call(w,"RenderBackupJobs");Wait((Task)Call(w,"RefreshHistoryAsync")!);Check(((StackPanel)w.FindName("JobsContent")).Children.OfType<Expander>().Any(e=>(e.Header as string)?.Contains("이동 1건")==true),"Direct move history hidden because backup count is zero");}finally{Close(w);}});
        Test("recommended-and-direct-buttons-fit-wpf-dialog",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{dialog=(Window)Call(w,"BuildMovePlan",new List<Package>{p},Path.Combine(dir,"library"))!;var body=(FrameworkElement)dialog.Content;body.Measure(new Size(840,720));body.Arrange(new Rect(0,0,840,720));body.UpdateLayout();var buttons=Logical(body).OfType<Button>().ToList();Check(Logical(body).OfType<System.Windows.Controls.Primitives.ToggleButton>().Any(b=>b.Name=="BackupBeforeMove"&&b.IsChecked==true)&&buttons.Any(b=>b.Content as string=="보관함으로 옮기기"),"Move choices absent");Check(buttons.Where(b=>b.Content is string text&&text.Contains("이동")).All(b=>b.ActualWidth<1||b.TranslatePoint(new Point(),body).X+b.ActualWidth<=841),"Move choice clipped");var bitmap=new RenderTargetBitmap(840,720,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle((Brush)app.FindResource("Surface.Primary"),null,new Rect(0,0,840,720));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(Path.Combine(dir,"choices.png"));png.Save(output);}finally{dialog?.Close();Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
